function doFocus(field, initVal){
  var obj = document.getElementById(field);
  if (obj.value == initVal) obj.value = ''; 
}

contactName.addEventListener(      'blur', doBlur.bind(null, 'contactName',         name_init ), false);
contactEmail.addEventListener(     'blur', doBlur.bind(null, 'contactEmail',     address_init ), false);
contactBusiness.addEventListener(  'blur', doBlur.bind(null, 'contactBusiness', business_init ), false);
contactMessage.addEventListener(   'blur', doBlur.bind(null, 'contactMessage',   message_init ), false);

function doBlur(field, initVal){
  var obj = document.getElementById(field);
  if (obj.value == '') obj.value = initVal;
}

