function submitForm(){
//contactSendButton.blur();

  if (!email_is_valid(contactEmail.value)){
    contactStatus.value = errAddress
    return true;
  }

  if (contactName.value == name_init){
    contactStatus.value = errName
    return true;
  }

  if (contactMessage.value == message_init){
    contactStatus.value = errMessage
    return true;
  }

  contactStatus.value = '';

  var regex = new RegExp(alert_char, 'g');
  var address= alert_email.replace(regex, '');

  var subject = "mail from test contact form";

  var body    = contactMessage.value;
  var nime    = '\n\n'+contactName.value;
      bizns   = '\n'+contactBusiness.value;
      email   = '\n'+contactEmail.value;
      body    = encodeURIComponent(body+nime+bizns+email);

  finalStr = `mailto:${address}?subject=${subject}&body=${body}`;
  location.href = finalStr;
}

//———————————————————————————————————————— functions

function email_is_valid(addr){
	re = /^[a-z,0-9,\.,_,-]+\@[a-z,0-9,\._,,-]+\.[a-z]+$/i;
	return re.test(addr);
}


